from functools import partial
from typing import Callable


class Task(object):
    """Wrapper for task."""

    def __init__(self, fn, *args, **kwargs):
        # type: (Callable, *Any, **Any) -> None
        """
        :param fn: function to be executed
        :param args: position arguments passed to function
        :param kwargs: keyword arguments passed to function. Can also contain callback for function.
        """
        assert isinstance(fn, Callable)
        self.fn = fn
        self.fn_callbacks = self._set_fn_callback(kwargs.pop("fn_callback", None))
        self.args = args
        self.kwargs = kwargs

    def run(self):
        # type: () -> partial
        """
        :return: partial of function with all position and keyword arguments to be called later
        """
        return partial(self.fn, *self.args, **self.kwargs)

    @staticmethod
    def _set_fn_callback(fn_callbacks):
        if fn_callbacks is not None:
            if isinstance(fn_callbacks, tuple):
                for fn in fn_callbacks:
                    assert isinstance(fn, Callable)
            else:
                assert isinstance(fn_callbacks, Callable)
            if not isinstance(fn_callbacks, tuple):
                fn_callbacks = (fn_callbacks,)
        else:
            fn_callbacks = []
        return fn_callbacks
